<template><div><h2>后台首页</h2><div class="metric-grid"><div class="metric"><small>图书总量</small><h2>{{ stats.total }}</h2></div><div class="metric"><small>可借库存</small><h2>{{ stats.available }}</h2></div><div class="metric"><small>借阅中</small><h2>{{ stats.borrowing }}</h2></div><div class="metric"><small>分类数</small><h2>{{ stats.categories }}</h2></div></div><div class="page-card welcome"><h3>系统概览</h3><p>通过左侧菜单管理图书、读者、公告和借阅业务。</p></div></div></template>
<script setup>import { reactive,onMounted } from 'vue';import http from '../api/http';const stats=reactive({total:0,available:0,borrowing:0,categories:0});onMounted(async()=>{const [books,cats]=await Promise.all([http.get('/books',{params:{page:1,size:1}}),http.get('/categories')]);stats.total=books.data.total;stats.available='-';stats.categories=cats.data.length})</script>
<style scoped>.welcome{margin-top:22px}</style>
